(() => {
  'use strict';
  const KEY='daymark:v1';
  const DAYS=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
  const DAY_KEYS=[1,2,3,4,5,6,0];
  const CATEGORIES=['Study','Health','Personal','Home','Work','Hobbies','Other'];
  const EMOJIS=['📚','💪','🧠','🏠','💼','🎨','🌱','💧','🧘','✍️','🎸','🌙','☀️','🧹','🏃','🥗','🐾','🎯'];
  const iso=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
  const fromIso=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)};
  const shift=(s,n)=>{const d=fromIso(s);d.setDate(d.getDate()+n);return iso(d)};
  const today=()=>iso(new Date());
  const fmt=(s,opts={weekday:'long',month:'long',day:'numeric'})=>fromIso(s).toLocaleDateString(undefined,opts);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid=()=>Math.random().toString(36).slice(2,10);
  const mondayIndex=d=>(d.getDay()+6)%7;
  const dateKey=(r,date)=>`${r.id}@${date}`;
  const defaults=()=>({user:{name:'',theme:'light',weekStartsMonday:true,onboarded:false},categories:[...CATEGORIES],routines:[
    {id:uid(),name:'Morning movement',description:'A little movement to wake up well.',icon:'💪',category:'Health',time:'07:00',days:[0,1,2,3,4,5,6],color:'#e9f3ed',paused:false},
    {id:uid(),name:'Read for 20 minutes',description:'A few pages of something good.',icon:'📚',category:'Personal',time:'08:30',days:[0,1,2,3,4,5,6],color:'#f1effb',paused:false},
    {id:uid(),name:'Drink a full glass of water',description:'Start hydrated, feel the difference.',icon:'💧',category:'Health',time:'09:00',days:[0,1,2,3,4,5,6],color:'#edf4f9',paused:false},
    {id:uid(),name:'Focused study session',description:'One clear hour, phone on silent.',icon:'🧠',category:'Study',time:'17:00',days:[1,2,3,4,5],color:'#f6f1e8',paused:false},
    {id:uid(),name:'Tidy my space',description:'Ten minutes to reset the room.',icon:'🏠',category:'Home',time:'19:00',days:[0,1,2,3,4,5,6],color:'#f3efea',paused:false},
    {id:uid(),name:'Wind down without screens',description:'Give tomorrow a gentler start.',icon:'🌙',category:'Personal',time:'21:30',days:[0,1,2,3,4,5,6],color:'#f0eef8',paused:false}
  ],statuses:{},coachMessages:[],selectedDate:today(),historyMonth:today().slice(0,7),filter:'All'});
  let state;let hasSavedState=false;try{const saved=localStorage.getItem(KEY);hasSavedState=Boolean(saved);state=saved?JSON.parse(saved):defaults()}catch{state=defaults()}
  if(!state.user)state.user={name:'',theme:'light'};
  // Earlier builds filled this example name automatically, which hid first-run setup.
  // Keep every saved routine and check-in, but ask the user to replace that placeholder.
  if(hasSavedState&&state.user.name==='Jamie Parker'&&!state.user.onboarded)state.user.name='';
  state.categories=state.categories||[...CATEGORIES];state.routines=state.routines||[];state.statuses=state.statuses||{};
  let page='dashboard';
  let cloudUid=null, cloudDoc=null, cloudUnsubscribe=null, cloudTimer=null, applyingCloud=false, cloudReady=false, cloudDirty=false, localRevision=0;
  const cloudKey=uid=>`${KEY}:user:${uid}`;
  function normalizeState(value){const d=defaults();if(!value||typeof value!=='object')return d;return {...d,...value,user:{...d.user,...(value.user||{})},categories:Array.isArray(value.categories)?value.categories:d.categories,routines:Array.isArray(value.routines)?value.routines:d.routines,statuses:value.statuses&&typeof value.statuses==='object'?value.statuses:d.statuses,coachMessages:Array.isArray(value.coachMessages)?value.coachMessages:[]}}
  let deferredInstallPrompt=null;
  const root=document.getElementById('page-root');
  function save(){try{const json=JSON.stringify(state);localStorage.setItem(cloudUid?cloudKey(cloudUid):KEY,json);if(cloudUid&&!applyingCloud&&cloudReady&&cloudDoc){cloudDirty=true;const revision=++localRevision;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>cloudDoc.set({state:JSON.parse(json),updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true}).then(()=>{if(revision===localRevision)cloudDirty=false}).catch(err=>{console.error('Daymark cloud save failed',err);toast('Saved on this device. Cloud sync failed; check your connection.') }),450)}return true}catch{toast('This browser blocked saving. Open Daymark in a normal browser window and allow site storage.');return false}}
  async function connectCloud(user){
    if(!window.firebase||!firebase.firestore||!user)return;
    if(cloudUid===user.uid&&cloudReady)return;
    if(cloudUnsubscribe)cloudUnsubscribe();clearTimeout(cloudTimer);cloudReady=false;applyingCloud=true;
    const previousUid=localStorage.getItem(`${KEY}:lastUid`),accountKey=cloudKey(user.uid),cached=localStorage.getItem(accountKey);
    let local;
    try{local=cached?normalizeState(JSON.parse(cached)):(!previousUid&&hasSavedState?normalizeState(JSON.parse(localStorage.getItem(KEY)||'{}')):defaults())}catch{local=defaults()}
    cloudUid=user.uid;state=local;
    if(!state.user.name){state.user.name=user.displayName||(user.email||'').split('@')[0]||'Friend';state.user.onboarded=true}
    localStorage.setItem(`${KEY}:lastUid`,user.uid);localStorage.setItem(accountKey,JSON.stringify(state));
    cloudDoc=firebase.firestore().collection('users').doc(user.uid);
    try{
      const snap=await cloudDoc.get();
      if(cloudUid!==user.uid)return;
      if(snap.exists&&snap.data().state){state=normalizeState(snap.data().state);localStorage.setItem(accountKey,JSON.stringify(state))}
      else await cloudDoc.set({state,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
      cloudReady=true;cloudDirty=false;applyingCloud=false;applyTheme();render();
      if(cloudUnsubscribe)cloudUnsubscribe();
      cloudUnsubscribe=cloudDoc.onSnapshot(snapshot=>{if(!snapshot.exists||!snapshot.data().state||cloudDirty)return;const incoming=normalizeState(snapshot.data().state),current=JSON.stringify(state);if(JSON.stringify(incoming)===current)return;applyingCloud=true;state=incoming;try{localStorage.setItem(accountKey,JSON.stringify(state))}catch{}applyingCloud=false;applyTheme();render();toast('Your Daymark data synced')},err=>{console.error('Daymark cloud listener failed',err);toast('Cloud sync paused. Your data is still saved on this device.')});
    }catch(err){if(cloudUid!==user.uid)return;cloudReady=false;applyingCloud=false;console.error('Daymark cloud connection failed',err);toast('Could not sync your account. Check Firebase setup and Firestore rules.')}
  }
  function disconnectCloud(){if(!cloudUid)return;if(cloudUnsubscribe)cloudUnsubscribe();cloudUnsubscribe=null;clearTimeout(cloudTimer);cloudUid=null;cloudDoc=null;cloudReady=false;applyingCloud=false;cloudDirty=false;state=defaults();page='dashboard';render()}
  window.daymarkCloudSync={connect:connectCloud,disconnect:disconnectCloud};
  function scheduled(r,date){return (!r.paused||date<today())&&Array.isArray(r.days)&&r.days.includes(fromIso(date).getDay())}
  function status(r,date){return state.statuses[dateKey(r,date)]||'pending'}
  function setStatus(r,date,value){if(value==='pending')delete state.statuses[dateKey(r,date)];else state.statuses[dateKey(r,date)]=value;save()}
  function dayStats(date){const list=state.routines.filter(r=>scheduled(r,date));const completed=list.filter(r=>status(r,date)==='completed').length;const missed=list.filter(r=>status(r,date)==='missed').length;return{list,completed,missed,pending:list.length-completed-missed,pct:list.length?Math.round(completed/list.length*100):0}}
  function streak(r){let cursor=today();if(scheduled(r,cursor)&&status(r,cursor)==='missed')return 0;if(!scheduled(r,cursor)||status(r,cursor)!=='completed')cursor=shift(cursor,-1);let count=0;for(let i=0;i<3650;i++){if(scheduled(r,cursor)){if(status(r,cursor)==='completed')count++;else break}cursor=shift(cursor,-1)}return count}
  function longestStreak(r){const dates=Object.keys(state.statuses).filter(k=>k.startsWith(r.id+'@')).map(k=>k.slice(r.id.length+1)).sort();if(!dates.length)return 0;let best=0,run=0;const start=shift(dates[0],-365);for(let d=start;d<=dates[dates.length-1];d=shift(d,1)){if(!scheduled(r,d))continue;if(status(r,d)==='completed'){run++;best=Math.max(best,run)}else run=0}return best}
  function weeklyStats(){const t=today(),idx=mondayIndex(fromIso(t)),start=shift(t,-idx);return Array.from({length:7},(_,i)=>{const date=shift(start,i);return{date,label:DAYS[i],...dayStats(date)}})}
  function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'}
  function motivation(s){if(s.list.length&&s.completed===s.list.length)return'Beautifully done. You showed up for every routine today.';if(s.list.length===0)return'Add a routine that makes your day feel a little better.';if(s.pending===s.list.length)return'A fresh day is a fresh chance to begin.';if(s.pending===1)return'One more routine to go. You’ve got this.';if(s.pct>=75)return'You’re doing wonderfully. Keep your rhythm.';if(s.pct>0)return'Every small step counts. Keep going at your pace.';return'No rush. Pick one small thing and start there.'}
  function completionMark(s){return s==='completed'?'✓':s==='missed'?'×':'·'}
  function syncChrome(){const name=state.user.name||'Your name';document.getElementById('profile-name').textContent=name;document.getElementById('avatar').textContent=(name.trim()[0]||'Y').toUpperCase();document.getElementById('top-avatar').textContent=(name.trim()[0]||'Y').toUpperCase();document.getElementById('top-date').textContent=fmt(today(),{month:'short',day:'numeric',year:'numeric'});document.getElementById('crumb-current').textContent=({dashboard:'Overview',history:'Calendar',statistics:'Insights',routines:'My routines',coach:'Routine Coach',settings:'Settings'})[page];document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page))}
  function shellHead(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
  function stateButtons(r,date){const s=status(r,date);return `<div class="routine-actions"><button class="state-button ${s==='completed'?'done':''}" data-status="completed" data-id="${r.id}" data-date="${date}" aria-label="Mark ${esc(r.name)} completed" title="Completed">✓</button><button class="state-button ${s==='missed'?'missed':''}" data-status="missed" data-id="${r.id}" data-date="${date}" aria-label="Mark ${esc(r.name)} not completed" title="Not completed">×</button><button class="state-button" data-status="pending" data-id="${r.id}" data-date="${date}" aria-label="Reset ${esc(r.name)} to pending" title="Reset to pending">↺</button></div>`}
  function routineCard(r,date){const s=status(r,date);return `<article class="routine-card state-${s}"><div class="routine-emoji" style="background:${esc(r.color||'#f5f4ef')}">${esc(r.icon)}</div><div class="routine-main"><div class="routine-title">${esc(r.name)}${s==='completed'?'<span class="routine-badge">Done</span>':s==='missed'?'<span class="routine-badge">Not today</span>':''}</div>${r.description?`<div class="routine-description">${esc(r.description)}</div>`:''}<div class="routine-meta"><span>◷ ${esc(r.time?new Date(`2000-01-01T${r.time}`).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'Anytime')}</span><span class="category-dot"><i class="tiny-dot"></i>${esc(r.category)}</span>${streak(r)>1?`<span>♨ ${streak(r)} day streak</span>`:''}</div></div>${stateButtons(r,date)}</article>`}
  function dashboard(){const date=state.selectedDate||today(),s=dayStats(date),categories=['All',...new Set(state.routines.map(r=>r.category))],visible=s.list.filter(r=>state.filter==='All'||r.category===state.filter);const week=weeklyStats();const overall=state.routines.filter(r=>scheduled(r,today()));const topStreak=Math.max(0,...state.routines.map(streak));
   root.innerHTML=`${shellHead('YOUR DAY',`${greeting()}, ${esc((state.user.name||'friend').split(' ')[0])} 👋`,fmt(date)+ (date===today()?'':' · Looking back'),'<button class="primary-button" id="add-routine"><span class="plus">＋</span>Add routine</button>')}
   <div class="dashboard-grid"><section class="progress-card"><div class="eyebrow">TODAY’S PROGRESS</div><h2>${s.completed===s.list.length&&s.list.length?'A day to be proud of':'Make today count, one step at a time.'}</h2><div class="progress-sub">${esc(motivation(s))}</div><div class="progress-bottom"><div style="flex:1"><div class="progress-big">${s.completed}<small> / ${s.list.length} complete</small></div><div class="progress-track"><div class="progress-fill" style="width:${s.pct}%"></div></div></div><div class="progress-note">${s.pct}%</div></div></section>
   <section class="streak-card"><div class="streak-head"><span class="eyebrow">YOUR RHYTHM</span><span class="streak-glyph">♨</span></div><div class="streak-value">${topStreak} <small>day${topStreak===1?'':'s'}</small></div><div class="streak-copy">${topStreak?'Your best current routine streak':'A new rhythm starts today'}</div><div class="week-dots">${week.map(x=>`<div class="week-day"><span>${x.label[0]}</span><span class="week-dot ${x.date===today()?'today':''} ${x.list.length&&x.pct===100?'done':''}">${x.list.length&&x.pct===100?'✓':x.date===today()?'•':''}</span></div>`).join('')}</div></section></div>
   <div class="section-heading"><h2>${date===today()?"Today's routines":fmt(date,{weekday:'short',month:'long',day:'numeric'})}</h2><span class="muted">${s.completed} completed · ${s.pending} to go</span></div><div class="filter-row">${categories.map(c=>`<button class="filter-chip ${state.filter===c?'selected':''}" data-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="routine-list">${visible.length?visible.map(r=>routineCard(r,date)).join(''):`<div class="empty-state"><strong>${s.list.length?'Nothing in this category':'A little room for a new routine'}</strong>${s.list.length?'Choose another filter to see your routines.':'Create a routine that brings you closer to what matters.'}${!s.list.length?'<br><br><button class="primary-button" id="add-routine-empty">＋ Add your first routine</button>':''}</div>`}</div>
   <div class="bottom-panels"><section class="panel"><div class="panel-title"><h3>This week</h3><button data-page="statistics">View insights ↗</button></div><div class="weekly-bars">${week.map(x=>`<div class="bar-day"><span class="bar-pct">${x.list.length?x.pct+'%':'—'}</span><div class="bar-track"><div class="bar-fill ${x.date===today()?'today':''}" style="height:${x.pct}%"></div></div><span class="bar-label">${x.label}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-title"><h3>A gentle reminder</h3><span style="color:#c5ac75">✳</span></div><div class="focus-card"><span class="focus-label">A thought for today</span><p>Consistency beats perfection.</p><small>Small steps add up to meaningful change.</small></div></section></div>`;
   root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;save();render()});root.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>changeStatus(b.dataset.id,b.dataset.date,b.dataset.status));root.querySelectorAll('#add-routine,#add-routine-empty').forEach(b=>b.onclick=()=>openRoutine());
  }
  function changeStatus(id,date,value){const r=state.routines.find(x=>x.id===id);if(!r)return;const before=dayStats(date);setStatus(r,date,value);const after=dayStats(date);render();if(value==='completed'&&after.list.length&&after.completed===after.list.length&&before.completed<before.list.length){celebrate();toast('Perfect day! Every routine is complete.')}else toast(value==='completed'?'Marked complete':value==='missed'?'Marked not completed':'Back to pending')}
  function celebrate(){const c=document.createElement('div');c.className='confetti';for(let i=0;i<65;i++){const p=document.createElement('i');p.style.left=Math.random()*100+'%';p.style.background=['#4d9168','#edc86c','#d88679','#8db8c7','#b8a3d7'][i%5];p.style.animationDelay=Math.random()*.55+'s';p.style.animationDuration=(1.2+Math.random())+'s';c.appendChild(p)}document.body.append(c);setTimeout(()=>c.remove(),2600)}
  function monthShift(month,delta){const [y,m]=month.split('-').map(Number);const d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
  function history(){const month=state.historyMonth||today().slice(0,7),[y,m]=month.split('-').map(Number),first=new Date(y,m-1,1,12),offset=mondayIndex(first),daysInMonth=new Date(y,m,0).getDate(),cells=Math.ceil((offset+daysInMonth)/7)*7;let html='';for(let i=0;i<cells;i++){const n=i-offset+1,d=new Date(y,m-1,n,12),date=iso(d),inMonth=d.getMonth()===m-1,s=dayStats(date),score=s.list.length?s.pct+'%':'';const tone=s.list.length?(s.pct>=80?'completed':s.pct>=40?'partial':'low'):'';html+=`<div class="calendar-day ${inMonth?'':'outside'} ${date===today()?'today':''} ${state.selectedDate===date?'selected':''}" data-date="${date}"><span class="day-number">${d.getDate()}</span>${s.list.length?`<br><i class="day-dot ${tone}"></i><span class="day-score">${score}</span>`:''}</div>`}
   const date=state.selectedDate||today(),s=dayStats(date);root.innerHTML=`${shellHead('LOOK BACK','Your calendar','A little progress, day by day.') }<section class="page-surface"><div class="calendar-header"><h2>${first.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><div class="month-controls"><button id="prev-month" aria-label="Previous month">‹</button><button id="next-month" aria-label="Next month">›</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${html}</div><div class="history-detail"><div class="history-detail-head"><h3>${esc(fmt(date))}</h3><span class="detail-score">${s.list.length?`${s.completed} of ${s.list.length} · ${s.pct}%`:'No routines scheduled'}</span></div>${s.list.length?s.list.map(r=>`<div class="history-row"><span>${esc(r.icon)} &nbsp;${esc(r.name)}</span><span class="history-state ${status(r,date)}">${status(r,date)==='completed'?'✓ Completed':status(r,date)==='missed'?'× Not completed':'· Pending'}</span></div>`).join(''):'<div class="empty-state">There are no scheduled routines for this day.</div>'}</div></section><div class="section-heading"><h2>How to read your calendar</h2></div><div class="filter-row"><span class="filter-chip"><i class="day-dot completed"></i> &nbsp;80%+ completed</span><span class="filter-chip"><i class="day-dot partial"></i> &nbsp;40–79% completed</span><span class="filter-chip"><i class="day-dot low"></i> &nbsp;Under 40%</span></div>`;
   root.querySelector('#prev-month').onclick=()=>{state.historyMonth=monthShift(month,-1);save();render()};root.querySelector('#next-month').onclick=()=>{state.historyMonth=monthShift(month,1);save();render()};root.querySelectorAll('.calendar-day').forEach(el=>el.onclick=()=>{state.selectedDate=el.dataset.date;save();render()})
  }
  function stats(){const t=today(),todayS=dayStats(t),week=weeklyStats(),month=t.slice(0,7),dates=Object.keys(state.statuses).filter(k=>k.slice(k.indexOf('@')+1).startsWith(month+'-')&&state.statuses[k]==='completed'),monthTotal=state.routines.reduce((sum,r)=>sum+Array.from({length:fromIso(t).getDate()},(_,i)=>{const d=`${month}-${String(i+1).padStart(2,'0')}`;return scheduled(r,d)?1:0}).reduce((a,b)=>a+b,0),0),monthCompleted=dates.length,monthPct=monthTotal?Math.round(monthCompleted/monthTotal*100):0;const total=state.routines.length,totals=state.routines.map(r=>{let n=0,c=0;for(let i=0;i<30;i++){const d=shift(t,-i);if(scheduled(r,d)){n++;if(status(r,d)==='completed')c++}}return{r,pct:n?Math.round(c/n*100):0,streak:streak(r)}}).sort((a,b)=>b.pct-a.pct);const completedAll=Object.entries(state.statuses).filter(([k,v])=>v==='completed').length;
   root.innerHTML=`${shellHead('YOUR PROGRESS','Small steps add up.','A clear view of the routines you’re building.') }<div class="stats-cards"><article class="stat-card"><span class="stat-card-icon">☷</span><div class="stat-card-label">ACTIVE ROUTINES</div><div class="stat-card-value">${state.routines.filter(r=>!r.paused).length}</div><div class="stat-card-note">${total} in your collection</div></article><article class="stat-card"><span class="stat-card-icon">✓</span><div class="stat-card-label">COMPLETED TODAY</div><div class="stat-card-value">${todayS.completed}<small style="font:500 12px 'DM Sans';color:#929a91"> / ${todayS.list.length}</small></div><div class="stat-card-note">${todayS.pct}% of today’s routines</div></article><article class="stat-card"><span class="stat-card-icon">♨</span><div class="stat-card-label">BEST CURRENT STREAK</div><div class="stat-card-value">${Math.max(0,...state.routines.map(streak))}<small style="font:500 12px 'DM Sans';color:#929a91"> days</small></div><div class="stat-card-note">Across your routines</div></article><article class="stat-card"><span class="stat-card-icon">◷</span><div class="stat-card-label">THIS MONTH</div><div class="stat-card-value">${monthPct}<small style="font:500 12px 'DM Sans';color:#929a91">%</small></div><div class="stat-card-note">${monthCompleted} completed · ${monthTotal} scheduled</div></article></div><div class="analytics-grid"><section class="chart-panel"><h3>This week at a glance</h3><div class="chart-caption">Daily completion across all scheduled routines</div><div class="monthly-chart">${week.map((x,i)=>`<div class="monthly-column"><div class="monthly-bar-wrap"><div class="monthly-bar ${x.date===today()?'current':''}" style="height:${x.pct}%"></div></div><small>${x.list.length?x.pct+'%':'—'}</small><small>${DAYS[i]}</small></div>`).join('')}</div></section><section class="chart-panel"><h3>Your most consistent</h3><div class="chart-caption">Last 30 days · completed on scheduled days</div><div class="consistency-list">${totals.slice(0,5).map(x=>`<div class="consistency-row"><span class="consistency-emoji">${esc(x.r.icon)}</span><div><div class="consistency-name">${esc(x.r.name)}</div><div class="consistency-track"><div class="consistency-fill" style="width:${x.pct}%"></div></div></div><span class="consistency-pct">${x.pct}%</span></div>`).join('')||'<div class="empty-state">Add a routine to start building your insights.</div>'}</div></section></div><div class="bottom-panels"><section class="panel"><div class="panel-title"><h3>Routine streaks</h3><button data-page="routines">Manage routines ↗</button></div><div class="consistency-list">${totals.slice(0,6).map(x=>`<div class="consistency-row"><span class="consistency-emoji">${esc(x.r.icon)}</span><div><div class="consistency-name">${esc(x.r.name)}</div><div class="consistency-track"><div class="consistency-fill" style="width:${x.pct}%"></div></div></div><span class="consistency-pct">♨ ${x.streak}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-title"><h3>Your journey</h3></div><div class="focus-card"><span class="focus-label">ALL TIME</span><p>${completedAll} routines completed</p><small>${total} routines in your collection · Keep showing up for yourself.</small></div><div class="focus-card" style="margin-top:10px"><span class="focus-label">A KIND REMINDER</span><p>Progress isn’t always a straight line.</p><small>Every day is another chance to begin.</small></div></section></div>`;
  }
  function routinesPage(){root.innerHTML=`${shellHead('YOUR LIBRARY','My routines','Shape a routine list that fits your life.',`<button class="primary-button" id="add-routine"><span class="plus">＋</span>Add routine</button>`)}<div class="routine-table">${state.routines.length?state.routines.map(r=>`<article class="manage-card"><div class="routine-emoji" style="background:${esc(r.color||'#f5f4ef')}">${esc(r.icon)}</div><div class="routine-main"><div class="routine-title">${esc(r.name)}${r.paused?'<span class="routine-badge" style="background:#f2f3f0;color:#899188">Paused</span>':''}</div><div class="routine-meta"><span>${esc(r.category)}</span><span>${esc((r.days||[]).length===7?'Every day':(r.days||[]).length===5?'Weekdays':(r.days||[]).length===2?'Weekends':(r.days||[]).map(d=>DAYS[DAY_KEYS.indexOf(d)]).join(', ')||'No days')}</span><span>${esc(r.time||'Anytime')}</span></div></div><div class="manage-stats"><span><b>${streak(r)}</b>streak</span><span><b>${longestStreak(r)}</b>best</span></div><div class="manage-actions"><button data-edit="${r.id}">Edit</button><button data-pause="${r.id}">${r.paused?'Resume':'Pause'}</button><button data-delete="${r.id}" aria-label="Delete ${esc(r.name)}">×</button></div></article>`).join(''):'<div class="empty-state"><strong>Your routine library is ready for you.</strong>Add your first routine and build from there.<br><br><button class="primary-button" id="add-routine">＋ Add a routine</button></div>'}</div>`;
   root.querySelectorAll('#add-routine').forEach(b=>b.onclick=()=>openRoutine());root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openRoutine(b.dataset.edit));root.querySelectorAll('[data-pause]').forEach(b=>b.onclick=()=>{const r=state.routines.find(x=>x.id===b.dataset.pause);r.paused=!r.paused;save();render();toast(r.paused?'Routine paused':'Routine resumed')});root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const r=state.routines.find(x=>x.id===b.dataset.delete);if(!r)return;openConfirm(`Delete “${r.name}”?`,'This removes the routine and its history. This can’t be undone.',()=>{state.routines=state.routines.filter(x=>x.id!==r.id);Object.keys(state.statuses).forEach(k=>{if(k.startsWith(r.id+'@'))delete state.statuses[k]});save();render();toast('Routine deleted')})})
  }
  function coachReply(prompt){
    const q=prompt.toLowerCase(),active=state.routines.filter(r=>!r.paused),week=weeklyStats().filter(d=>d.date<=today()),weekTotal=week.reduce((n,d)=>n+d.list.length,0),weekDone=week.reduce((n,d)=>n+d.completed,0),weekPct=weekTotal?Math.round(weekDone/weekTotal*100):0,todayStats=dayStats(today()),easy=active.find(r=>/5|10|min|water|stretch|walk|read/i.test(r.name))||active[0];
    if(/can't breathe|cannot breathe|chest pain|overdose|suicid|kill myself|hurt myself|emergency/i.test(q))return{ text:'This sounds urgent. Please contact your local emergency service now, or tell someone nearby who can stay with you. I can help with routines, but I can’t assess an emergency.' };
    if(/diagnos|symptom|medication|medicine|dose|pain|sick|illness|disease|treatment|doctor|medical|injur/i.test(q))return{ text:'I can help you shape everyday routines, but I can’t diagnose symptoms or recommend medicines or treatment. A qualified health professional can give advice for your situation. If symptoms are severe or sudden, seek urgent medical care.' };
    if(!active.length)return{ text:'Your routine list is clear right now. A gentle place to start is one tiny habit you can finish in a few minutes. Try a short stretch or a few pages of reading, then build only if it feels useful.',suggestion:{name:'Take a 5-minute stretch break',category:'Health',icon:'🧘',time:''} };
    if(/tired|low energy|overwhelm|overwhelmed|stress|busy|hard to start|motivat/i.test(q))return{ text:`Let’s make today lighter. You have ${todayStats.pending} routine${todayStats.pending===1?'':'s'} still pending today. Pick one easy win${easy?`—“${easy.name}” could be a good place to begin`:''}—and shrink it to five minutes if needed. Rest is part of a sustainable routine, too.` };
    if(/health|healthy|well.?being|wellness|sleep|exercise|water|food|nutrition|diet/i.test(q))return{ text:'For general wellbeing, keep the basics gentle and consistent: a regular wind-down, some comfortable movement, and water when you’re thirsty can support a routine. Needs vary by person, so treat this as general information, not medical advice. What part of your day would you like to make easier?' };
    if(/improv|review|week|progress|consisten|streak|miss|fall behind|routine/i.test(q)){
      if(active.length>=8)return{ text:`Your week is at ${weekPct}% completion (${weekDone} of ${weekTotal} scheduled check-ins). With ${active.length} active routines, simplifying may help: pause one that matters least right now, or make its first step smaller. Which routine feels hardest to keep?` };
      const weak=active.map(r=>{let n=0,c=0;for(let i=0;i<7;i++){const d=shift(today(),-i);if(scheduled(r,d)){n++;if(status(r,d)==='completed')c++}}return{r,n,pct:n?c/n:1}}).filter(x=>x.n).sort((a,b)=>a.pct-b.pct)[0];
      return{ text:`You completed ${weekDone} of ${weekTotal} scheduled check-ins this week (${weekPct}%). ${weak&&weak.pct<.6?`“${weak.r.name}” has been the trickiest lately. Try attaching it to something you already do, or reduce it to a two-minute version for a week.`:'Your routine list looks manageable. Keep the timing and first step clear, and aim for consistency over perfection.'} Missing a day doesn’t erase your progress.` };
    }
    if(/add|suggest|new habit|new routine|start/i.test(q))return{ text:'A small habit is easier to repeat. Here’s a simple option you can personalize. Select “Add this routine” to review it before saving.',suggestion:{name:'Take a 5-minute stretch break',category:'Health',icon:'🧘',time:''} };
    return{ text:`I can help you simplify a routine, review your week, or find a gentle way to restart. This week you’re at ${weekPct}% completion. What’s one routine you’d like to make easier?` };
  }
  function coachPage(){
    const messages=Array.isArray(state.coachMessages)?state.coachMessages:[],week=weeklyStats().filter(d=>d.date<=today());
    const aiReady=Boolean(window.daymarkAI?.configured()),aiConsent=localStorage.getItem('daymark:ai-consent:v1')==='yes';
    root.innerHTML=`${shellHead('A GENTLER WAY FORWARD','AI Routine Coach','A thoughtful companion for your routines, your pace, and your week.')}<section class="coach-layout"><div class="coach-main panel"><div class="coach-title-row"><div class="coach-orb" aria-hidden="true">✦</div><div><h2>Your routine companion</h2><p>Personalized coaching powered by Gemini through Firebase.</p></div><span class="coach-status ${aiReady?'':'coach-status-setup'}"><i></i>${aiReady?'Gemini ready':'Firebase setup needed'}</span></div><div class="coach-privacy">Your chat stays with your Daymark data. Before the first AI reply, you’ll choose whether to send your message and a short routine summary to Google’s Gemini. No name or email is sent. Health and urgent-safety questions are handled on this device and are not sent to Gemini.</div><div class="coach-messages" id="coach-messages" aria-live="polite">${messages.length?messages.slice(-24).map(m=>`<article class="coach-message ${m.role==='user'?'from-user':'from-coach'}"><span class="coach-message-icon">${m.role==='user'?'☺':'✦'}</span><div><b>${m.role==='user'?'You':'AI Routine Coach'}</b><p>${esc(m.text).replace(/\n/g,'<br>')}</p>${m.suggestion?`<button class="secondary-button coach-add" data-coach-add="${esc(m.suggestion.name)}" data-category="${esc(m.suggestion.category)}" data-icon="${esc(m.suggestion.icon)}">Review this routine</button>`:''}</div></article>`).join(''):`<article class="coach-message from-coach"><span class="coach-message-icon">✦</span><div><b>AI Routine Coach</b><p>Hi ${esc((state.user.name||'there').split(' ')[0])}! Ask me to review your week, make a routine easier, or find one manageable next step. I’ll use your routine list to make the ideas personal.</p></div></article>`}</div><div class="coach-prompts"><button class="coach-chip" data-coach-prompt="Help me make my routines easier to stick with">Make my routines easier</button><button class="coach-chip" data-coach-prompt="Review how my week is going">Review my week</button><button class="coach-chip" data-coach-prompt="I feel low on energy; what is a gentle next step?">I feel low on energy</button><button class="coach-chip" data-coach-prompt="Suggest a small healthy routine I could start">Suggest a small habit</button></div><form class="coach-form" id="coach-form"><label class="visually-hidden" for="coach-input">Ask the Routine Coach</label><textarea id="coach-input" maxlength="500" rows="2" placeholder="Ask about your routine…" required></textarea><button class="primary-button" aria-label="Send message">Send <span aria-hidden="true">↑</span></button></form><p class="coach-disclaimer">General routine and wellbeing ideas only—not medical advice or a substitute for a health professional.</p><p class="coach-consent-status">${aiConsent?'AI replies are enabled. You can turn this off any time in this section.':'AI sharing is off until you approve the first request.'} ${aiConsent?'<button type="button" id="coach-disable-ai">Turn off AI replies</button>':''}</p></div><aside class="coach-side"><section class="panel coach-week"><div class="eyebrow">YOUR WEEK SO FAR</div><strong>${week.reduce((n,d)=>n+d.completed,0)} <small>of ${week.reduce((n,d)=>n+d.list.length,0)}</small></strong><p>scheduled routines checked off</p><div class="progress-track"><div class="progress-fill" style="width:${week.reduce((n,d)=>n+d.list.length?d.pct:0,0)/Math.max(1,week.filter(d=>d.list.length).length)}%"></div></div></section><section class="coach-side-note"><span>✧</span><h3>Small is a strategy.</h3><p>Start with the easiest next step. You can adjust your plan whenever life changes.</p></section></aside></section>`;
    const box=root.querySelector('#coach-messages');box.scrollTop=box.scrollHeight;
    root.querySelector('#coach-form').onsubmit=e=>{e.preventDefault();const input=root.querySelector('#coach-input'),value=input.value.trim();if(value)coachAsk(value)};
    root.querySelector('#coach-disable-ai')?.addEventListener('click',()=>{localStorage.removeItem('daymark:ai-consent:v1');render();toast('AI sharing turned off')});
  }
  function coachContext(){const week=weeklyStats().filter(d=>d.date<=today());return{today:{scheduled:dayStats(today()).list.length,completed:dayStats(today()).completed,pending:dayStats(today()).pending},week:{completed:week.reduce((n,d)=>n+d.completed,0),scheduled:week.reduce((n,d)=>n+d.list.length,0)},routines:state.routines.filter(r=>!r.paused).map(r=>({name:r.name,category:r.category,time:r.time||'unscheduled',days:(r.days||[]).map(d=>DAYS[DAY_KEYS.indexOf(d)]),last7:Array.from({length:7},(_,i)=>shift(today(),-i)).filter(d=>scheduled(r,d)).map(d=>status(r,d))})).slice(0,20)}}
  function coachRoutineIdea(text){const match=String(text||'').match(/(?:^|\n)Routine idea:\s*([^|\n]{2,70})\s*\|\s*([^|\n]{2,24})\s*\|\s*(\S+)/i);if(!match)return null;const category=match[2].trim(),icon=Array.from(match[3].trim())[0]||'🌱';return{end:match.index, suggestion:{name:match[1].trim(),category:CATEGORIES.some(x=>x.toLowerCase()===category.toLowerCase())?category:'Personal',icon}}}
  function localSafetyPrompt(prompt){return /can't breathe|cannot breathe|chest pain|overdose|suicid|kill myself|hurt myself|emergency|diagnos|symptom|medication|medicine|\bdose\b|\bpain\b|\bsick\b|illness|disease|treatment|doctor|medical|injur/i.test(prompt)}
  function askAiConsent(prompt){const modal=document.getElementById('modal-root');modal.innerHTML=`<div class="modal-backdrop"><section class="modal ai-consent-modal" role="dialog" aria-modal="true" aria-labelledby="ai-consent-title"><div class="modal-header"><div><div class="eyebrow">YOUR CHOICE</div><h2 id="ai-consent-title">Use Gemini for coaching?</h2><p>Daymark will send your message and a short summary of active routine names, schedules, and recent check-ins to Google’s Gemini through Firebase AI Logic, so it can tailor its reply.</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-body"><p>Your name and email are not included. Gemini responses can be wrong. Please don’t share diagnoses, medication details, or emergency information; use a qualified health professional for medical advice. Your chat is saved in Daymark according to your account’s sync settings.</p><label class="ai-consent-check"><input type="checkbox" id="ai-consent-checkbox"/><span>I understand this information will be sent to Gemini for a reply.</span></label></div><div class="modal-footer"><button type="button" class="secondary-button ai-consent-cancel">Keep AI off</button><button type="button" class="primary-button ai-consent-allow" disabled>Continue to Gemini</button></div></section></div>`;const checkbox=modal.querySelector('#ai-consent-checkbox'),allow=modal.querySelector('.ai-consent-allow');modal.querySelector('.modal-close').onclick=closeModal;modal.querySelector('.ai-consent-cancel').onclick=closeModal;modal.querySelector('.modal-backdrop').onclick=e=>{if(e.target===modal)closeModal()};checkbox.onchange=()=>{allow.disabled=!checkbox.checked};allow.onclick=()=>{localStorage.setItem('daymark:ai-consent:v1','yes');closeModal();runCoachPrompt(prompt)}}
  async function runCoachPrompt(prompt){state.coachMessages=Array.isArray(state.coachMessages)?state.coachMessages:[];if(localSafetyPrompt(prompt)){state.coachMessages.push({role:'assistant',...coachReply(prompt)});state.coachMessages=state.coachMessages.slice(-48);save();render();toast('This question stayed on your device');return}state.coachMessages.push({role:'user',text:prompt.slice(0,500)});state.coachMessages=state.coachMessages.slice(-48);save();render();const messages=root.querySelector('#coach-messages'),form=root.querySelector('#coach-form');messages.insertAdjacentHTML('beforeend','<article class="coach-message from-coach" id="coach-loading"><span class="coach-message-icon">✦</span><div><b>AI Routine Coach</b><p>Thinking about your next step…</p></div></article>');messages.scrollTop=messages.scrollHeight;form.querySelector('button').disabled=true;try{if(!window.daymarkAI?.configured()){state.coachMessages.push({role:'assistant',text:`Gemini isn’t enabled in Firebase yet, so I couldn’t send this for an AI reply. ${coachReply(prompt).text}`})}else{const text=await window.daymarkAI.reply(prompt,coachContext()),idea=coachRoutineIdea(text);state.coachMessages.push({role:'assistant',text:idea?text.slice(0,idea.end).trim():text,...(idea?{suggestion:idea.suggestion}:{})})}}catch(error){console.error('Daymark AI request failed',error);state.coachMessages.push({role:'assistant',text:`I couldn’t reach Gemini just now. ${coachReply(prompt).text}`})}state.coachMessages=state.coachMessages.slice(-48);save();render()}
  function coachAsk(prompt){const value=String(prompt||'').trim().slice(0,500);if(!value)return;if(localSafetyPrompt(value)||!window.daymarkAI?.configured()){runCoachPrompt(value);return}if(localStorage.getItem('daymark:ai-consent:v1')!=='yes'){askAiConsent(value);return}runCoachPrompt(value)}
  function bindInstallButton(button){if(button&&deferredInstallPrompt)button.onclick=async()=>{deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;render();if(choice.outcome==='accepted')toast('Daymark installed')}}
  function settings(){const installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;root.innerHTML=`${shellHead('MAKE IT YOURS','Settings','A few small details to make Daymark feel like your space.') }<div class="settings-grid"><section class="settings-block"><h3>Your profile</h3><p>How we greet you and personalize your space.</p><form id="profile-form"><div class="form-field"><label for="setting-name">Your name</label><input id="setting-name" name="name" value="${esc(state.user.name)}" maxlength="40" required /></div><button class="primary-button">Save changes</button></form></section><section class="settings-block"><h3>Appearance</h3><p>Choose a comfortable look for your day.</p><div class="form-field"><label for="theme-select">Color theme</label><select id="theme-select"><option value="light" ${state.user.theme!=='dark'?'selected':''}>Light</option><option value="dark" ${state.user.theme==='dark'?'selected':''}>Dark</option></select></div><p>Changes are saved on this device.</p></section><section class="settings-block install-block"><h3>Install Daymark</h3><p>Add Daymark to your home screen or desktop for an app-like window.</p><button class="primary-button" id="install-app" disabled>Install options</button><p class="install-hint">Use your browser menu to install Daymark or add it to your home screen.</p></section><section class="settings-block install-block"><h3>Install Daymark</h3><p>Add Daymark to your home screen or desktop for an app-like window.</p><button class="primary-button" id="install-app" disabled>Install options</button><p class="install-hint">Use your browser menu to install Daymark or add it to your home screen.</p></section><section class="settings-block"><h3>Your categories</h3><p>Keep your routine list organized with categories.</p><form id="category-form"><div class="form-field"><label for="category-name">Add a category</label><input id="category-name" name="category" placeholder="e.g. Creative time" maxlength="24" required /></div><button class="primary-button">＋ Add category</button></form><div class="filter-row" style="flex-wrap:wrap;margin:14px 0 0">${state.categories.map(c=>`<span class="filter-chip">${esc(c)}</span>`).join('')}</div></section><section class="settings-block"><h3>Your data</h3><p>Your routines and history stay in this browser.</p><button class="secondary-button" id="export-data">Download my data</button> <button class="secondary-button" id="reset-data">Start fresh</button><p style="margin-top:12px">${state.routines.length} routines · saved locally on this device</p></section></div>`;
   const installButton=root.querySelector('#install-app');if(installButton){installButton.textContent=installed?'Already installed':deferredInstallPrompt?'Install Daymark':'Install options';installButton.disabled=installed||!deferredInstallPrompt;bindInstallButton(installButton)}root.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();state.user.name=new FormData(e.currentTarget).get('name').trim();save();render();toast('Your name has been updated')};root.querySelector('#theme-select').onchange=e=>{state.user.theme=e.target.value;save();applyTheme();toast('Appearance updated')};root.querySelector('#category-form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.currentTarget).get('category').trim();if(value&&!state.categories.some(c=>c.toLowerCase()===value.toLowerCase()))state.categories.push(value);save();render();toast('Category added')};root.querySelector('#export-data').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`daymark-${today()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Your data download is ready')};root.querySelector('#reset-data').onclick=()=>openConfirm('Start fresh?','All routines, settings, and saved history on this device will be removed.',()=>{localStorage.removeItem(KEY);state=defaults();save();render();toast('Your space is ready for a fresh start')});const accountAction=root.querySelector('#account-action');if(accountAction)accountAction.onclick=()=>openAuthModal()
  }
  function applyTheme(){document.documentElement.dataset.theme=state.user.theme==='dark'?'dark':'light'}
  function welcome(){const name=state.user.name||'';root.innerHTML=`<section class="welcome-screen"><div class="welcome-card"><div class="welcome-brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="M8 21.5a8 8 0 0 1 16 0"/><path d="M11 21.5a5 5 0 0 1 10 0"/><path d="M16 8v3"/><path d="M7.8 13.1l2.1 2.1M24.2 13.1l-2.1 2.1"/><path d="M7 24h18"/></svg></span><span>daymark<span class="brand-period">.</span></span></div><div class="welcome-art" aria-hidden="true"><span class="welcome-sun"></span><span class="welcome-hill hill-back"></span><span class="welcome-hill hill-front"></span><span class="welcome-spark spark-one">✦</span><span class="welcome-spark spark-two">✳</span></div><div class="eyebrow">A LITTLE SPACE FOR YOU</div><h1>Make room for<br/>what matters.</h1><p class="welcome-copy">Build a rhythm that feels like yours. Let’s start with your name.</p><form id="welcome-form"><label for="welcome-name">What should we call you?</label><input id="welcome-name" name="name" type="text" maxlength="40" autocomplete="given-name" placeholder="Your name" value="${esc(name)}" required/><button class="primary-button welcome-submit">Let’s get started <span aria-hidden="true">→</span></button></form><div class="welcome-footnote"><span>✦</span> Small steps. Your pace. A fresh start.</div></div></section>`;const field=root.querySelector('#welcome-name');root.querySelector('#welcome-form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.currentTarget).get('name').trim();if(!value){field.focus();return}state.user.name=value;state.user.onboarded=true;save();render();toast(`Welcome, ${value.split(/\s+/)[0]}!`)};field.focus()}
  function render(){syncChrome();applyTheme();const needsName=!state.user.name;document.body.classList.toggle('needs-onboarding',needsName);if(needsName){welcome();return}({dashboard,history,statistics:stats,routines:routinesPage,coach:coachPage,settings})[page]()}
  function openRoutine(id,draft){const edit=state.routines.find(r=>r.id===id),r=edit||draft||{name:'',description:'',icon:'🌱',category:state.categories[0]||'Other',time:'',days:[0,1,2,3,4,5,6],color:'#e9f3ed'};const modal=document.getElementById('modal-root');modal.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="routine-modal-title"><div class="modal-header"><div><h2 id="routine-modal-title">${edit?'Edit routine':'Create a routine'}</h2><p>A small promise to yourself, made easy.</p></div><button class="modal-close" aria-label="Close">×</button></div><form id="routine-form"><div class="modal-body"><div class="form-field"><label for="routine-name">Routine name *</label><input id="routine-name" name="name" value="${esc(r.name)}" placeholder="e.g. Read for 20 minutes" maxlength="60" required /></div><div class="form-field"><label for="routine-description">A little note <span style="color:#a0a69e;font-weight:400">(optional)</span></label><textarea id="routine-description" name="description" maxlength="140" placeholder="What would make this routine feel good?">${esc(r.description)}</textarea></div><div class="form-field"><label>Choose an icon</label><div class="emoji-picker">${EMOJIS.map(e=>`<button type="button" class="emoji-option ${e===r.icon?'selected':''}" data-emoji="${e}">${e}</button>`).join('')}</div><input type="hidden" name="icon" value="${esc(r.icon)}" /></div><div class="form-row"><div class="form-field"><label for="routine-category">Category</label><select id="routine-category" name="category">${[...new Set([...state.categories,r.category])].map(c=>`<option ${c===r.category?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="form-field"><label for="routine-time">Time <span style="color:#a0a69e;font-weight:400">(optional)</span></label><input id="routine-time" name="time" type="time" value="${esc(r.time)}" /></div></div><div class="form-field"><label>Repeat on</label><div class="day-picker">${DAY_KEYS.map((d,i)=>`<label><input name="days" type="checkbox" value="${d}" ${(r.days||[]).includes(d)?'checked':''}/><span>${DAYS[i][0]}</span></label>`).join('')}</div></div></div><div class="modal-footer"><button type="button" class="secondary-button cancel">Cancel</button><button class="primary-button">${edit?'Save changes':'Create routine'}</button></div></form></section></div>`;
   modal.querySelector('.modal-close').onclick=closeModal;modal.querySelector('.cancel').onclick=closeModal;modal.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};modal.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{modal.querySelectorAll('[data-emoji]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');modal.querySelector('[name=icon]').value=b.dataset.emoji});modal.querySelector('#routine-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const name=fd.get('name').trim(),days=fd.getAll('days').map(Number);if(!name){modal.querySelector('#routine-name').focus();return}if(!days.length){toast('Choose at least one day for this routine');return}const data={name,description:fd.get('description').trim(),icon:fd.get('icon'),category:fd.get('category'),time:fd.get('time'),days,color:r.color||'#e9f3ed'};if(edit)Object.assign(edit,data);else state.routines.push({id:uid(),...data,paused:false});save();closeModal();render();toast(edit?'Routine updated':'Routine added to your day')};modal.querySelector('#routine-name').focus()
  }
  function openConfirm(title,body,onConfirm){const m=document.getElementById('modal-root');m.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(body)}</p></div><button class="modal-close">×</button></div><div class="modal-footer"><button class="secondary-button cancel">Cancel</button><button class="primary-button confirm">Continue</button></div></section></div>`;m.querySelector('.modal-close').onclick=closeModal;m.querySelector('.cancel').onclick=closeModal;m.querySelector('.confirm').onclick=()=>{closeModal();onConfirm()}}
  function closeModal(){document.getElementById('modal-root').innerHTML=''}
  function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.getElementById('toast-root').appendChild(t);setTimeout(()=>t.remove(),2500)}
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;const b=document.getElementById('install-app');if(b){b.textContent='Install Daymark';b.disabled=false;bindInstallButton(b)}});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;toast('Daymark is installed')});if('serviceWorker' in navigator&&(location.protocol==='http:'||location.protocol==='https:'))window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
  document.addEventListener('click',e=>{const prompt=e.target.closest('[data-coach-prompt]');if(prompt){coachAsk(prompt.dataset.coachPrompt);return}const add=e.target.closest('[data-coach-add]');if(add){openRoutine(undefined,{name:add.dataset.coachAdd,description:'Suggested by your Routine Coach. Adjust this idea to fit your day.',icon:add.dataset.icon||'🌱',category:add.dataset.category||'Personal',time:'',days:[0,1,2,3,4,5,6],color:'#e9f3ed'});return}const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;state.filter='All';save();render();window.scrollTo({top:0,behavior:'smooth'})}});document.getElementById('mobile-add').onclick=()=>openRoutine();document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
  render();
})();
